#!/run/current-system/sw/bin/python3
"""Durable asynchronous job service.

Entry points:
  jobservice.py api      - HTTP API on :8080
  jobservice.py worker   - background worker loop

Storage layout:
  /var/lib/job-store/<id>.json   durable job records (this service owns these)
  /var/lib/accepted-jobs/*.json  opaque pre-existing spool (imported, never modified)

Job record: {"id","payload","status","result","attempts"}
  status in {accepted, completed}
  completed => result == "processed:" + payload, attempts == 1
"""
import json
import os
import re
import time
import uuid

STORE = "/var/lib/job-store"
SPOOL = "/var/lib/accepted-jobs"

ID_RE = re.compile(r"^[A-Za-z0-9._-]{1,128}\Z")


def ensure_dirs():
    os.makedirs(STORE, exist_ok=True)
    os.makedirs(SPOOL, exist_ok=True)


def job_path(job_id):
    return os.path.join(STORE, job_id + ".json")


def is_valid_id(job_id):
    return bool(ID_RE.match(job_id))


def _atomic_write_json(path, obj):
    tmp = "%s.tmp.%d.%s" % (path, os.getpid(), uuid.uuid4().hex)
    data = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def load_job(path):
    with open(path, "rb") as f:
        return json.loads(f.read().decode("utf-8"))


def list_jobs():
    for name in os.listdir(STORE):
        if name.endswith(".json"):
            yield os.path.join(STORE, name)


def create_accepted(job_id, payload):
    """Create a new accepted job. No-op (returns existing) if id already present.

    Uses O_EXCL so concurrent creators cannot clobber an existing record (which
    may already be completed)."""
    path = job_path(job_id)
    try:
        fd = os.open(path, os.O_CREAT | os.O_WRONLY | os.O_EXCL, 0o644)
    except FileExistsError:
        return load_job(path)
    obj = {
        "id": job_id,
        "payload": payload,
        "status": "accepted",
        "result": None,
        "attempts": 0,
    }
    data = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
    with os.fdopen(fd, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    return obj


def import_spool():
    """Recover opaque work from the pre-existing spool into our durable store.

    The spool files are left untouched. Each id is imported at most once
    (O_EXCL create). Already-completed records are never overwritten."""
    if not os.path.isdir(SPOOL):
        return
    for name in sorted(os.listdir(SPOOL)):
        if not name.endswith(".json"):
            continue
        src = os.path.join(SPOOL, name)
        try:
            with open(src, "rb") as f:
                rec = json.loads(f.read().decode("utf-8"))
        except (OSError, ValueError):
            continue
        job_id = rec.get("id")
        payload = rec.get("payload", "")
        if not isinstance(job_id, str) or not is_valid_id(job_id):
            continue
        # Only import if we do not already have it (preserve completed work).
        if os.path.exists(job_path(job_id)):
            continue
        create_accepted(job_id, payload)


def process_pending():
    """Process every accepted job in the store exactly once."""
    import_spool()
    for path in list_jobs():
        try:
            job = load_job(path)
        except (OSError, ValueError):
            continue
        if job.get("status") != "accepted":
            continue
        payload = job.get("payload", "")
        updated = {
            "id": job["id"],
            "payload": payload,
            "status": "completed",
            "result": "processed:" + payload,
            "attempts": 1,
        }
        _atomic_write_json(path, updated)


# ----------------------------- HTTP API ---------------------------------

def run_api():
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import urlparse

    ensure_dirs()
    import_spool()

    class Handler(BaseHTTPRequestHandler):
        server_version = "jobservice/1.0"

        def _send(self, code, body=b"", content_type="text/plain; charset=utf-8"):
            if isinstance(body, str):
                body = body.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(body)

        def log_message(self, *args):
            pass  # quiet

        def do_GET(self):
            path = urlparse(self.path).path
            if path == "/health":
                self._send(200, "ready")
                return
            if path.startswith("/jobs/"):
                job_id = path[len("/jobs/"):]
                if not is_valid_id(job_id):
                    self._send(400, "bad id")
                    return
                jp = job_path(job_id)
                if not os.path.exists(jp):
                    # maybe newly dropped in the opaque spool
                    import_spool()
                if not os.path.exists(jp):
                    self._send(404, "not found")
                    return
                try:
                    job = load_job(jp)
                except (OSError, ValueError):
                    self._send(500, "corrupt")
                    return
                self._send(200, json.dumps(job, ensure_ascii=False),
                           "application/json")
                return
            self._send(404, "not found")

        def do_POST(self):
            path = urlparse(self.path).path
            if not path.startswith("/jobs/"):
                self._send(404, "not found")
                return
            job_id = path[len("/jobs/"):]
            if not is_valid_id(job_id):
                self._send(400, "bad id")
                return
            length = int(self.headers.get("Content-Length") or 0)
            payload = self.rfile.read(length) if length > 0 else b""
            payload = payload.decode("utf-8", errors="surrogateescape")
            create_accepted(job_id, payload)
            self._send(202, "")

    httpd = ThreadingHTTPServer(("0.0.0.0", 8080), Handler)
    httpd.serve_forever()


# ----------------------------- Worker ----------------------------------

def run_worker():
    ensure_dirs()
    # Process the opaque work promptly on startup.
    process_pending()
    while True:
        process_pending()
        time.sleep(0.5)


def main():
    import sys
    mode = sys.argv[1] if len(sys.argv) > 1 else ""
    if mode == "api":
        run_api()
    elif mode == "worker":
        run_worker()
    else:
        print("usage: jobservice.py {api|worker}", file=sys.stderr)
        raise SystemExit(2)


if __name__ == "__main__":
    main()

